window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"pace":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"速度"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"步法"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"缓慢走"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"踱步于"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"步调"}],"examples":[{"sentence":"The pace of technological change has forced workers to update their skills regularly.","translation":"技术变革的速度迫使劳动者不断更新自己的技能。","targetForm":"pace","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"At a steady pace, the guide led the group through the crowded market.","translation":"导游以稳定的步速带领大家穿过拥挤的市场。","targetForm":"pace","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The doctor asked him to pace himself during recovery instead of returning to work too soon.","translation":"医生让他在康复期间量力而行，不要过早返岗。","targetForm":"pace","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Unable to sleep, she began to pace along the corridor outside the ward.","translation":"她无法入睡，便开始在病房外的走廊上踱步。","targetForm":"pace","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The debate moved at a slow pace because each proposal required careful translation.","translation":"由于每项提议都需要仔细翻译，辩论进行得很缓慢。","targetForm":"pace","senseId":"source-n-2","sourceSenseId":"n-2"}]},"palace":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"宫殿"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"华丽大厦"}],"examples":[{"sentence":"The grand palace, which served as the royal residence for centuries, now functions as a museum that attracts millions of visitors annually.","translation":"这座宏伟的宫殿曾作为皇家住所数个世纪，如今作为博物馆每年吸引数百万游客。","targetForm":"palace","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"During the tour, the guide explained that the palace was constructed with marble imported from distant quarries.","translation":"在参观期间，导游解释说这座宫殿是用从遥远采石场进口的大理石建造的。","targetForm":"palace","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The government decided to restore the ancient palace, which had suffered damage from centuries of neglect and environmental factors.","translation":"政府决定修复这座因几个世纪的忽视和环境因素而受损的古老宫殿。","targetForm":"palace","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Many palaces in Europe, including Versailles, showcase the opulence and artistic achievements of their respective eras.","translation":"欧洲的许多宫殿，包括凡尔赛宫，展示了各自时代的奢华与艺术成就。","targetForm":"palaces","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The newly built cultural center, often called a palace of the arts, hosts international exhibitions and performances throughout the year.","translation":"这座新建的文化中心常被称为艺术殿堂，全年举办国际展览和演出。","targetForm":"palace","senseId":"source-n-3","sourceSenseId":"n-3"}]},"paw":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"爪"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"以蹄扒地"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"用爪子抓"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"拼命抓"}],"examples":[{"sentence":"The cat gently placed its paw on my hand, a gesture that seemed to seek attention and comfort.","translation":"猫轻轻地把爪子放在我的手上，这个动作似乎是在寻求关注和安慰。","targetForm":"paw","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The dog injured its paw while running across the rocky terrain, which required immediate veterinary care.","translation":"狗在多石的地面上奔跑时弄伤了爪子，需要立即接受兽医护理。","targetForm":"paw","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The horse pawed the ground impatiently, signaling its readiness to begin the long journey ahead.","translation":"马不耐烦地用蹄子刨着地面，表明它已准备好开始漫长的旅程。","targetForm":"pawed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The bear pawed at the fallen log, searching for insects hidden beneath the decaying bark.","translation":"熊用爪子抓挠倒下的原木，寻找藏在腐烂树皮下的昆虫。","targetForm":"pawed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"In a frantic effort to escape, the trapped animal pawed desperately at the cage door until it finally opened.","translation":"为了拼命逃脱，被困的动物绝望地抓挠笼门，直到门终于打开。","targetForm":"pawed","senseId":"source-v-3","sourceSenseId":"v-3"}]},"participant":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"参与者"}],"examples":[{"sentence":"As an observer and participant in global capital markets, three of these risks stand out to me.","translation":"作为一名观察者兼国际资本市场的参与者，我看到了三大新萌发的风险。","targetForm":"participant","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because each participant in the study signed a consent form, the researchers could ethically collect sensitive data.","translation":"由于研究中的每位参与者都签署了同意书，研究人员可以合乎道德地收集敏感数据。","targetForm":"participant","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The workshop required every participant to contribute a case study, thereby ensuring a diverse range of perspectives.","translation":"研讨会要求每位参与者贡献一个案例研究，从而确保了多样化的视角。","targetForm":"participant","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A participant who withdraws from the trial without notifying the coordinator may compromise the validity of the results.","translation":"未通知协调员就退出试验的参与者可能会损害结果的有效性。","targetForm":"participant","senseId":"source-n-2","sourceSenseId":"n-2"}]},"paper":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"纸"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"文件"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"文章"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"报纸"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"证券"}],"examples":[{"sentence":"She sketched the design on recycled paper before meeting the client, so the team could compare several possibilities.","translation":"她在见客户前把设计草图画在再生纸上，这样团队就能比较几种方案。","targetForm":"paper","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before the visa interview, he arranged every paper in the order requested by the consulate.","translation":"签证面谈前，他按照领事馆要求的顺序整理好每一份文件。","targetForm":"paper","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Her paper argues that public libraries strengthen communities by giving young people a quiet place to study.","translation":"她的论文认为，公共图书馆为年轻人提供安静的学习场所，因此能增强社区凝聚力。","targetForm":"paper","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although most readers now follow breaking news online, her grandfather still reads the paper over breakfast.","translation":"尽管多数读者如今在网上关注突发新闻，她的祖父早餐时仍会读报纸。","targetForm":"paper","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The fund reduced its exposure to risky commercial paper when interest rates began to rise.","translation":"利率开始上升时，该基金降低了对高风险商业票据的敞口。","targetForm":"paper","senseId":"source-n-5","sourceSenseId":"n-5"}]},"partial":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"部分的"}],"examples":[{"sentence":"A partial analysis of the data may lead to misleading conclusions if researchers ignore confounding variables.","translation":"如果研究人员忽略混杂变量，对数据的部分分析可能会导致误导性结论。","targetForm":"partial","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the reform achieved partial success in urban areas, its impact on rural communities was far less pronounced.","translation":"尽管改革在城市地区取得了部分成功，但其对农村社区的影响远没有那么明显。","targetForm":"partial","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the funding was only partial, the research team had to scale back the scope of their investigation.","translation":"由于资金只是部分的，研究团队不得不缩减调查范围。","targetForm":"partial","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The committee reached only a partial consensus because several members remained unconvinced by the evidence presented.","translation":"委员会只达成了部分共识，因为几位成员对所呈证据仍持怀疑态度。","targetForm":"partial","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The historian warned that relying on a partial account of events could distort our understanding of the past.","translation":"历史学家警告说，依赖对事件的部分叙述可能会扭曲我们对过去的理解。","targetForm":"partial","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"path":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"路径"}],"examples":[{"sentence":"Nor are these claims based on the Chinese stock market, which has generally followed a downward path over the past few years.","translation":"过热的说法也并非以股市为依据，因为过去几年来，股市一直处于下降通道之中。","targetForm":"path","senseId":"source-n-1","sourceSenseId":"n-1"}]},"patience":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"耐性"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"忍耐"}],"examples":[{"sentence":"Although learning a language demands patience, regular practice produces gradual and lasting improvement.","translation":"尽管学习一门语言需要耐心，规律练习会带来逐步而持久的进步。","targetForm":"patience","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the experiment failed several times, the scientist needed patience to refine the method rather than abandon it.","translation":"由于实验多次失败，科学家需要耐心改进方法，而不是放弃它。","targetForm":"patience","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Teachers must exercise patience when they explain difficult concepts so that every student can follow the reasoning.","translation":"教师解释难懂概念时必须保持耐心，才能让每位学生跟上推理过程。","targetForm":"patience","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Without patience, the delicate process of negotiating a peace treaty would be likely to collapse.","translation":"没有耐心，谈判和平条约这一精细过程很可能会失败。","targetForm":"patience","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Her patience with difficult customers resolved complaints and, over time, built genuine loyalty.","translation":"她对难缠顾客的耐心解决了投诉，并逐渐建立起真正的忠诚度。","targetForm":"patience","senseId":"source-n-2","sourceSenseId":"n-2"}]},"parasite":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"寄生生物"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"寄生虫"}],"examples":[{"sentence":"A parasite that depends entirely on its host often evolves to avoid causing immediate fatal harm.","translation":"完全依赖宿主的寄生生物往往会进化出避免立即造成致命伤害的特征。","targetForm":"parasite","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In many ecosystems, a parasite can regulate host populations and thereby affect wider biodiversity.","translation":"在许多生态系统中，寄生生物能调节宿主种群，进而影响更广泛的生物多样性。","targetForm":"parasite","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although a parasite is often seen as destructive, it can drive hosts to develop stronger immune defences.","translation":"尽管寄生生物常被视为有害，它也可能促使宿主形成更强的免疫防御。","targetForm":"parasite","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Researchers study the malaria parasite in order to identify weaknesses that may improve future treatment.","translation":"研究人员研究疟原虫，以找出可能改善未来治疗的弱点。","targetForm":"parasite","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When a parasite infects a keystone species, its effects can spread through the entire food web.","translation":"当寄生生物感染关键物种时，它的影响可能扩散到整个食物网。","targetForm":"parasite","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pattern":{"senseGroups":[{"id":"source-n-7","partOfSpeech":"n.","sourceSenseIds":["n-7"],"sense":"模式"}],"examples":[{"sentence":"Against that backdrop, one can assess current growth patterns in the global economy and its various parts.","translation":"在上述背景下，我们可以对全球经济目前的增长模式及其组成部分进行评估。","targetForm":"patterns","senseId":"source-n-7","sourceSenseId":"n-7"},{"sentence":"Unless and until US consumption patterns change or a rebounding dollar increases oil production, Americans will bear the brunt of single-currency oil pricing.","translation":"除非并且直到美国人的消费模式发生改变或者美元反弹从而增加石油产量，美国人将首当其冲的受到石油用单一货币计价的影响。","targetForm":"patterns","senseId":"source-n-7","sourceSenseId":"n-7"},{"sentence":"This pattern can be only partly repeated in the eurozone, where both debt socialization and a return to normal risk assessment appear more difficult.","translation":"这一模式在欧洲只能部分被复制，因为在欧洲，债务社会化和正常风险评估的回归都要更加困难。","targetForm":"pattern","senseId":"source-n-7","sourceSenseId":"n-7"}]},"particular":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"详细说明"}],"examples":[{"sentence":"I am happy to refer those seeking further particulars to one such former practicing physician: my wife.","translation":"我很高兴地推荐一位曾经使用这类系统的执业医师给那些希望进一步了解这些问题的人：我的夫人。","targetForm":"particulars","senseId":"source-n-4","sourceSenseId":"n-4"}]},"patch":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"斑"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"补缀"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"软件补丁","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"补缀"}],"examples":[{"sentence":"Although the garden was mostly barren, a bright patch of wildflowers attracted bees in the corner.","translation":"尽管花园大部分荒芜，角落里一片鲜艳的野花仍吸引了蜜蜂。","targetForm":"patch","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The tailor added a patch to the child's coat so that it could be worn through another winter.","translation":"裁缝给孩子的外套补了一块补丁，使它还能再穿过一个冬天。","targetForm":"patch","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"After the update, the team applied a security patch that closed a serious software vulnerability.","translation":"更新后，团队安装了一个安全补丁，修复了严重的软件漏洞。","targetForm":"patch","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Before the exhibition opened, volunteers patched the torn canvas and cleaned the wooden frame.","translation":"展览开幕前，志愿者修补了破损的帆布，并清洁了木框。","targetForm":"patched","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The leaders tried to patch up their disagreement before it damaged the coalition's wider work.","translation":"领导人试图在分歧损害联盟更广泛的工作前弥合它。","targetForm":"patch","senseId":"source-v-1","sourceSenseId":"v-1"}]},"party":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"政党"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"党"}],"examples":[{"sentence":"One hopes that what emerges from the parties’ nominating processes is insight into how the successful candidates answer three big questions.","translation":"人们希望从两党提名程序中脱颖而出的是能深刻理解成功候选人如何回答这三大问题。","targetForm":"parties","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Such statements sounded new to Chinese ears, because they accentuated politics rather than trumpeting the Party’s usual emphasis on economic determinism.","translation":"这些说法对于今天的中国人来说相当新鲜的，因为这些说法都是强调政治因素的重要性，而非党以往经常强调的经济决定论。","targetForm":"party","senseId":"source-n-2","sourceSenseId":"n-2"}]},"pasture":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"牧场"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"放牧"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"吃草"}],"examples":[{"sentence":"The farmer rotated his cattle to a fresh pasture every few weeks to maintain the quality of the grass.","translation":"这位农民每隔几周就把他的牛群轮换到新的牧场，以保持草的质量。","targetForm":"pasture","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Expansive green pastures stretched across the valley, providing an ideal setting for the dairy herd.","translation":"广阔的绿色牧场延伸至山谷，为奶牛群提供了理想的环境。","targetForm":"pastures","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The shepherd decided to pasture the sheep on the lower slopes where the grass was more abundant.","translation":"牧羊人决定在牧草更丰茂的低坡上放牧羊群。","targetForm":"pasture","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"During the dry season, the nomadic tribes pasture their livestock near the remaining water sources.","translation":"在旱季，游牧部落在剩余的水源附近放牧他们的牲畜。","targetForm":"pasture","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The horses pastured peacefully in the meadow, undisturbed by the distant sound of traffic.","translation":"马群在草地上安静地吃草，不受远处交通噪音的打扰。","targetForm":"pastured","senseId":"source-v-2","sourceSenseId":"v-2"}]},"passion":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"热爱"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"激情"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"酷爱"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"强烈感情"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"耶稣受难(故事)"}],"examples":[{"sentence":"Her passion for classical music led her to establish a foundation that supports young musicians.","translation":"她对古典音乐的热爱促使她成立了一个支持年轻音乐家的基金会。","targetForm":"passion","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The speaker's passion was evident as he addressed the audience with fervent conviction about climate change.","translation":"演讲者向听众讲述气候变化时，其激情显而易见，充满了热切的信念。","targetForm":"passion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He pursued his passion for astronomy by spending countless nights observing the stars through his telescope.","translation":"他通过无数个夜晚用望远镜观察星星来追求自己对天文学的酷爱。","targetForm":"passion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The novel explores the destructive power of unchecked passion, which ultimately leads to the protagonist's downfall.","translation":"这部小说探讨了不受约束的强烈感情所具有的破坏力，这种感情最终导致了主人公的垮台。","targetForm":"passion","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The cathedral's stained-glass windows depict scenes from the Passion of Christ with remarkable artistry.","translation":"大教堂的彩色玻璃窗以非凡的艺术手法描绘了耶稣受难故事中的场景。","targetForm":"Passion","senseId":"source-n-5","sourceSenseId":"n-5"}]},"paradox":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"悖论"}],"examples":[{"sentence":"LONDON – The election of Jeremy Corbyn as the new leader of the British Labour Party is a reminder that life is rich with paradox.","translation":"伦敦 — — 杰瑞米·柯比当选为英国工党新领袖提醒我们生活到处充满了悖论。","targetForm":"paradox","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A well-known paradox in environmental policy is that technological efficiency gains often lead to higher overall resource consumption.","translation":"环境政策中一个众所周知的悖论是，技术效率的提高往往导致总体资源消耗增加。","targetForm":"paradox","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The fact that social media connects people globally while simultaneously increasing feelings of isolation presents a modern paradox.","translation":"社交媒体在全球范围内连接人们的同时却加剧了孤独感，这一事实构成了一个现代悖论。","targetForm":"paradox","senseId":"source-n-3","sourceSenseId":"n-3"}]},"pain":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"疼痛"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使痛苦"}],"examples":[{"sentence":"Although the patient described the pain as unbearable, the doctor remained calm and gave fast-acting relief.","translation":"尽管病人说疼痛难以忍受，医生仍保持冷静并给予快速起效的缓解治疗。","targetForm":"pain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because chronic pain can contribute to depression, treatment often combines physical therapy with psychological support.","translation":"由于慢性疼痛可能导致抑郁，治疗通常会把物理治疗与心理支持结合起来。","targetForm":"pain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The researcher argued that pain is a complex experience shaped by physical, emotional, and cultural factors.","translation":"研究者认为，疼痛是受身体、情感和文化因素塑造的复杂体验。","targetForm":"pain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the athlete ignored sharp pain in her knee, she worsened the injury and had to leave the tournament.","translation":"当这名运动员忽视膝盖剧痛时，她加重了伤势，不得不退出比赛。","targetForm":"pain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The loss of the old library pained residents who had relied on it as a quiet place to study.","translation":"失去旧图书馆使居民感到痛苦，他们曾把它当作安静学习的场所。","targetForm":"pained","senseId":"source-v-1","sourceSenseId":"v-1"}]},"panorama":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"全景"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"全貌"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"概论"}],"examples":[{"sentence":"From the summit, we admired a breathtaking panorama of snow-capped mountains and winding rivers that stretched to the horizon.","translation":"从山顶望去，我们欣赏到一幅令人叹为观止的全景，雪峰和蜿蜒的河流一直延伸到天际。","targetForm":"panorama","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The historian's latest book offers a comprehensive panorama of medieval Europe, covering political, social, and cultural developments.","translation":"这位历史学家的新书提供了中世纪欧洲的全貌，涵盖了政治、社会和文化发展。","targetForm":"panorama","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The course provides a broad panorama of modern art movements, from Impressionism to contemporary installations.","translation":"这门课程提供了现代艺术运动的广阔概览，从印象派到当代装置艺术。","targetForm":"panorama","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The documentary presented a vivid panorama of life in the Amazon rainforest, highlighting both its beauty and its fragility.","translation":"这部纪录片生动地展现了亚马逊雨林生活的全貌，突出了其美丽与脆弱。","targetForm":"panorama","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The exhibition displayed a fascinating panorama of technological innovations that have shaped the 21st century.","translation":"展览展示了塑造21世纪的技术创新的迷人概览。","targetForm":"panorama","senseId":"source-n-3","sourceSenseId":"n-3"}]},"part":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"部分"}],"examples":[{"sentence":"Against that backdrop, one can assess current growth patterns in the global economy and its various parts.","translation":"在上述背景下，我们可以对全球经济目前的增长模式及其组成部分进行评估。","targetForm":"parts","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"How we answer these questions will in large part determine whether, in a relentlessly globalizing world, fear has the last word.","translation":"我们对这些问题的答案将在很大程度上决定，在这个残酷地全球化的世界中，恐惧是否是最后的特征。","targetForm":"part","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pack":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"包裹"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"一伙"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"一副"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"背包"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"包装"}],"examples":[{"sentence":"Each pack of tablets carries a clear warning label so that patients can check the dosage before leaving the pharmacy.","translation":"每包药片都附有清晰的警示标签，方便患者离开药房前核对剂量。","targetForm":"pack","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A pack of reporters waited outside the courthouse, hoping that a witness would comment after the verdict.","translation":"一群记者守在法院外，希望判决后能有证人发表评论。","targetForm":"pack","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"During the power cut, the children played cards with an old pack that they found in a kitchen drawer.","translation":"停电期间，孩子们用在厨房抽屉里找到的一副旧纸牌玩牌。","targetForm":"pack","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because her pack was light and well organised, the hiker could find the map without unpacking everything.","translation":"因为她的背包轻便且整理有序，这位徒步者无需把所有东西都拿出来便找到了地图。","targetForm":"pack","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Before the field trip, students packed waterproof clothing and enough food for the entire day.","translation":"实地考察前，学生们打包了防水衣物和足够吃一天的食物。","targetForm":"packed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"payment":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"付款"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"支付的款项(或实物)"}],"examples":[{"sentence":"When a payment is processed through a secure gateway, sensitive financial data is encrypted to prevent fraud.","translation":"当付款通过安全网关处理时，敏感的财务数据会被加密以防止欺诈。","targetForm":"payment","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the initial payment was made on time, subsequent installments were delayed due to administrative errors.","translation":"尽管首付款按时支付，但由于行政错误，后续分期付款被延迟了。","targetForm":"payment","senseId":"source-n-2","sourceSenseId":"n-2"}]},"pant":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"喘息"}],"examples":[{"sentence":"I went to the clothing store yesterday and bought a blue blouse and three pairs of pants.","translation":"昨天我去衣服店买了一件蓝色的衬衫和三件裤子。","targetForm":"pants","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom rolled up his pant legs so people could see his bright red socks.","translation":"汤姆卷起了他的裤腿，好让人看到他鲜红色的袜子。","targetForm":"pant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The tailor is going to redo the hem of my pants.","translation":"裁缝师要帮我重新修裤脚。","targetForm":"pants","senseId":"source-n-1","sourceSenseId":"n-1"}]},"patrol":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"侦察队"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"巡逻"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"巡逻"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"巡视"}],"examples":[{"sentence":"The border patrol intercepted a group attempting to cross illegally during the night.","translation":"边境巡逻队拦截了一群试图在夜间非法越境的人。","targetForm":"patrol","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A routine patrol discovered the breach in the perimeter fence early this morning.","translation":"今天清晨，一次例行巡逻发现了围栏上的缺口。","targetForm":"patrol","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Security guards patrol the shopping mall every hour to deter potential thieves.","translation":"保安每小时在购物中心巡逻一次，以震慑潜在的小偷。","targetForm":"patrol","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Police officers have been patrolling the neighborhood more frequently since the recent incidents.","translation":"自最近的事件以来，警察更频繁地在社区巡逻。","targetForm":"patrolling","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The coast guard vessel patrolled the waters to prevent illegal fishing activities.","translation":"海岸警卫队船只巡视海域以防止非法捕鱼活动。","targetForm":"patrolled","senseId":"source-v-2","sourceSenseId":"v-2"}]},"pave":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"铺设"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"为...铺路"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"铺满"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"安排"}],"examples":[{"sentence":"The city council decided to pave the old dirt road with asphalt to improve transportation and reduce dust.","translation":"市议会决定用沥青铺设那条旧的土路，以改善交通并减少灰尘。","targetForm":"pave","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Her groundbreaking research paved the way for new treatments that have saved countless lives over the past decade.","translation":"她开创性的研究为过去十年拯救了无数生命的新疗法铺平了道路。","targetForm":"paved","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The courtyard was paved with intricate mosaics that depicted scenes from ancient mythology.","translation":"庭院里铺满了描绘古代神话场景的复杂马赛克。","targetForm":"paved","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Early exposure to diverse cultures can pave the way for a more inclusive and empathetic worldview in adulthood.","translation":"早期接触多元文化可以为成年后更具包容性和同理心的世界观铺平道路。","targetForm":"pave","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The committee carefully paved the agenda for the summit, ensuring that all critical issues would be addressed in a logical order.","translation":"委员会仔细安排了峰会的议程，确保所有关键问题都能按逻辑顺序得到讨论。","targetForm":"paved","senseId":"source-v-2","sourceSenseId":"v-2"}]},"patron":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"赞助人"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"顾客"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"保护人"}],"examples":[{"sentence":"The young artist found a generous patron who funded her first solo exhibition in the city center.","translation":"这位年轻艺术家找到了一位慷慨的赞助人，资助了她在市中心的首场个展。","targetForm":"patron","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Without the steady support of a wealthy patron, the composer would have struggled to stage his ambitious opera.","translation":"如果没有一位富有赞助人的稳定支持，这位作曲家将难以将他雄心勃勃的歌剧搬上舞台。","targetForm":"patron","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The café’s regular patrons often gathered in the corner to discuss literature and politics over coffee.","translation":"这家咖啡馆的常客们经常聚在角落里，一边喝咖啡一边讨论文学和政治。","targetForm":"patrons","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"As a loyal patron of the local bookstore, she was invited to the exclusive author signing event.","translation":"作为当地书店的忠实顾客，她被邀请参加了那场专属的作者签售活动。","targetForm":"patron","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In medieval times, a patron saint was believed to offer protection to a particular group or place.","translation":"在中世纪，人们相信守护圣徒会为特定的群体或地方提供保护。","targetForm":"patron","senseId":"source-n-3","sourceSenseId":"n-3"}]},"participate":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"参与"}],"examples":[{"sentence":"Second, more women must participate in post-disaster counseling efforts, especially in regions where women survivors may not be as comfortable speaking with men about their trauma.","translation":"其次，必须有更多女性参与灾后咨询，特别是在女幸存者不太方便向男性说出自己的情况的地区。","targetForm":"participate","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"With Russia ostensibly on board, it is up to the US to initiate a transformation in the nuclear-negotiation framework – and that means convincing China to participate.","translation":"因为俄罗斯表面上愿意配合，需要由美国启动核谈判框架的转型工作 — — 这意味着要说服中国参与到谈判过程中。","targetForm":"participate","senseId":"source-v-3","sourceSenseId":"v-3"}]},"palm":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"手掌"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"棕榈"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"藏...于掌中"}],"examples":[{"sentence":"She placed the cracked seed in her palm, where its delicate pattern became visible under the reading lamp.","translation":"她把裂开的种子放在掌心，在台灯下其细致纹理清晰可见。","targetForm":"palm","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A line of palm trees sheltered the footpath, although the exposed coast remained hot throughout the afternoon.","translation":"一排棕榈树为人行道遮阴，尽管暴露的海岸整个下午依然炎热。","targetForm":"palm","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The magician palmed the coin before inviting the audience to inspect what appeared to be an empty hand.","translation":"魔术师先把硬币藏在掌中，再请观众检查那只看似空无一物的手。","targetForm":"palmed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because palm oil production affects tropical ecosystems, responsible buyers increasingly require transparent supply chains.","translation":"由于棕榈油生产影响热带生态系统，负责任的采购方越来越要求透明的供应链。","targetForm":"palm","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"He wrote the emergency number on his palm so that he could find it even after putting his phone away.","translation":"他把紧急电话号码写在掌心，以便收起手机后仍能找到它。","targetForm":"palm","senseId":"source-n-1","sourceSenseId":"n-1"}]},"patent":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"专利权"}],"examples":[{"sentence":"Universities often patent discoveries that arise from publicly funded research, thereby generating revenue to support further scientific inquiry.","translation":"大学通常为公共资助研究中产生的发现申请专利，从而产生收入以支持进一步的科学研究。","targetForm":"patent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A well-drafted patent application not only protects an invention but also signals a firm's commitment to research and development.","translation":"一份精心撰写的专利申请不仅保护发明，还表明公司对研发的承诺。","targetForm":"patent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the company failed to patent its core algorithm, competitors quickly replicated the technology and eroded its market share.","translation":"由于该公司未能为其核心算法申请专利，竞争对手迅速复制了该技术并侵蚀了其市场份额。","targetForm":"patent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the patent system is designed to reward inventors, it can sometimes hinder innovation when overly broad claims are granted.","translation":"尽管专利制度旨在奖励发明者，但当授予过于宽泛的权利要求时，它有时会阻碍创新。","targetForm":"patent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While the patent granted the startup a temporary monopoly, it also attracted venture capital that was essential for scaling production.","translation":"虽然该专利赋予了初创公司暂时的垄断地位，但它也吸引了对于扩大生产至关重要的风险投资。","targetForm":"patent","senseId":"source-n-1","sourceSenseId":"n-1"}]},"partner":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"伙伴"}],"examples":[{"sentence":"The reality, as a latter-day Caesar might put it, is that the fault is not in our trade partners, but in ourselves.","translation":"如果凯撒活到现在，他肯定会说，现实是错不在我们的贸易伙伴，而在我们自己。","targetForm":"partners","senseId":"source-n-3","sourceSenseId":"n-3"}]},"parachute":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"降落伞"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"跳伞"}],"examples":[{"sentence":"The museum displayed an early parachute beside diagrams that explained how its canopy slows a descent.","translation":"博物馆展出了一顶早期降落伞，并配以图示说明伞面如何减缓下降。","targetForm":"parachute","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the parachute looked simple, its fabric and stitching had to meet demanding engineering standards.","translation":"尽管降落伞看起来简单，它的布料和缝线仍必须达到严格的工程标准。","targetForm":"parachute","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The designers tested the parachute in a wind tunnel before allowing it to be used in a public demonstration.","translation":"设计人员在允许它用于公开演示前，先在风洞中测试了这顶降落伞。","targetForm":"parachute","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During the exercise, the team learned how to parachute supplies to an isolated research station without damaging fragile equipment.","translation":"演练中，团队学习如何向孤立的研究站空投物资，而不损坏脆弱设备。","targetForm":"parachute","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Rather than parachuting an unfamiliar manager into the project, the organisation promoted someone who knew the community.","translation":"该机构没有把陌生经理空降到项目中，而是提拔了了解社区的人。","targetForm":"parachuting","senseId":"source-v-1","sourceSenseId":"v-1"}]},"pay":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"薪资"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"支付"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"补偿"},{"id":"source-v-10","partOfSpeech":"v.","sourceSenseIds":["v-10"],"sense":"获得好处"}],"examples":[{"sentence":"Although the pay was not high, the post offered training that could lead to more stable work in the future.","translation":"尽管薪资不高，这份职位提供的培训可能带来更稳定的未来工作。","targetForm":"pay","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After corrected records revealed missing overtime, the council arranged back pay for workers who had completed the repairs.","translation":"更正记录显示加班费遗漏后，委员会为完成维修的工人安排了补发工资。","targetForm":"pay","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The museum agreed to pay the artists promptly, because delayed fees can prevent independent workers from continuing their practice.","translation":"博物馆同意及时支付艺术家报酬，因为拖延费用会阻碍独立工作者继续创作。","targetForm":"pay","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The company paid compensation to residents whose access had been disrupted while the street was being rebuilt.","translation":"公司向街道重建期间出行受影响的居民支付了补偿。","targetForm":"paid","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Careful preparation can pay off when a difficult question appears, because evidence is easier to explain under pressure.","translation":"当出现难题时，周密准备会带来回报，因为压力下证据更容易解释。","targetForm":"pay","senseId":"source-v-10","sourceSenseId":"v-10"}]},"past":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"过去"}],"examples":[{"sentence":"Nor are these claims based on the Chinese stock market, which has generally followed a downward path over the past few years.","translation":"过热的说法也并非以股市为依据，因为过去几年来，股市一直处于下降通道之中。","targetForm":"past","senseId":"source-n-1","sourceSenseId":"n-1"}]},"packet":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"小包"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"信息包"}],"examples":[{"sentence":"While a packet of instant soup offers convenience, preparing fresh ingredients provides greater nutritional value and flavor.","translation":"虽然一包速溶汤提供了便利，但准备新鲜食材能提供更高的营养价值和风味。","targetForm":"packet","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although a single packet of seeds seems insignificant, it can initiate a community garden that enhances neighborhood cohesion.","translation":"尽管一小包种子看起来微不足道，但它可以启动一个社区花园，从而增强邻里凝聚力。","targetForm":"packet","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because each data packet contains a header with routing information, it can be efficiently directed through complex networks.","translation":"因为每个数据包都包含一个带有路由信息的头部，所以它可以高效地通过复杂的网络进行引导。","targetForm":"packet","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The charity distributed a packet of essential supplies to each displaced family, which included hygiene items and basic food.","translation":"慈善机构向每个流离失所的家庭分发了一包必需品，其中包括卫生用品和基本食品。","targetForm":"packet","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pause":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"停顿"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"暂停"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"停顿"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"暂停"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"暂时停止批处理文件执行","contextReviewed":true}],"examples":[{"sentence":"After a short pause, the witness clarified the detail that had caused confusion during the earlier discussion.","translation":"短暂停顿后，证人澄清了先前讨论中引起困惑的细节。","targetForm":"pause","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the performance lasted two hours, a pause in the middle allowed the audience to stretch and reflect.","translation":"尽管演出持续两小时，中场休止让观众得以伸展身体并思考。","targetForm":"pause","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The presenter paused before answering because the question required a careful distinction between two similar claims.","translation":"发言者在回答前停顿了一下，因为这个问题需要仔细区分两个相似观点。","targetForm":"paused","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Before approving the contract, the director paused the negotiations until an independent review could be completed.","translation":"批准合同前，主任暂停谈判，直到独立审查完成。","targetForm":"paused","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The script used a pause command so that the batch process would wait for the operator's confirmation.","translation":"该脚本使用暂停命令，使批处理过程等待操作员确认。","targetForm":"pause","senseId":"source-other-1","sourceSenseId":"other-1"}]},"passport":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"护照"}],"examples":[{"sentence":"When you're beginning to look like the photo in your passport, you should go on a holiday.","translation":"当我们开始像自己护照上的照片时，我们该去度假了。","targetForm":"passport","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A passport is something you cannot do without when you go to a foreign country.","translation":"去外国旅行不能不带护照。","targetForm":"passport","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Sir, please present your passport or identity card, so I can register it.","translation":"先生，请出示护照或者身份证，让我登记一下。","targetForm":"passport","senseId":"source-n-1","sourceSenseId":"n-1"}]},"partly":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"部分地"}],"examples":[{"sentence":"This pattern can be only partly repeated in the eurozone, where both debt socialization and a return to normal risk assessment appear more difficult.","translation":"这一模式在欧洲只能部分被复制，因为在欧洲，债务社会化和正常风险评估的回归都要更加困难。","targetForm":"partly","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"passenger":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"乘客"}],"examples":[{"sentence":"There were only three passengers on the bus when it exploded.","translation":"当汽车爆炸时，车上只有三名乘客。","targetForm":"passengers","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"As the train came to a halt, all of the passengers wondered what was happening.","translation":"当列车停止时，所有的乘客都想知道发生了什么。","targetForm":"passengers","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Some brave passengers caught the pickpocket and turned him over to the police.","translation":"几位见义勇为的乘客把小偷抓住了，还把他送到了警方的手中。","targetForm":"passengers","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom put the large picnic basket on the passenger seat next to him.","translation":"汤姆把那个大野餐篮子放在他旁边的乘客座位上。","targetForm":"passenger","senseId":"source-n-1","sourceSenseId":"n-1"}]},"panic":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"恐慌"}],"examples":[{"sentence":"The EU must respond with a genuinely European asylum policy that will put an end to the panic and the unnecessary human suffering.","translation":"欧盟必须应之以能够结束恐慌和不必要的人道灾难的真正的欧洲庇护政策。","targetForm":"panic","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pan":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"平锅"}],"examples":[{"sentence":"While camping, Tom gave Mary dysentery by not thoroughly cleaning the pots and pans.","translation":"露营时，汤姆没有彻底清洗锅碗瓢盆，导致玛莉得了痢疾。","targetForm":"pans","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"You scorned both the Nymphs, who beheld your deeds, and me the mighty Pan.","translation":"你蔑视了目睹你罪行的仙女们，也蔑视了我を这位强大的潘神。","targetForm":"pan","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When sautéing vegetables, it is important to use a non-stick pan.","translation":"炒蔬菜时，重要的是使用不沾锅。","targetForm":"pan","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom and Mary's little boy loves sitting on the kitchen floor banging pots and pans.","translation":"汤姆和玛莉的小儿子喜欢坐在厨房地板上敲打锅碗瓢盆。","targetForm":"pans","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Cover the pan and cook until tender, then remove the cover and continue the cooking until the onions are a light brown.","translation":"盖上锅盖煮至洋葱变软，然后揭开锅盖继续煮至洋葱呈现浅棕色。","targetForm":"pan","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pair":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"一副"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"一双"}],"examples":[{"sentence":"I went to the clothing store yesterday and bought a blue blouse and three pairs of pants.","translation":"昨天我去衣服店买了一件蓝色的衬衫和三件裤子。","targetForm":"pairs","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"I bought this pair of shoes, but they are a bit too small.","translation":"我买了这双鞋，但是有点太小了。","targetForm":"pair","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There is a pair of worn red stockings in the drawer.","translation":"抽屉里有一双穿过的红色丝袜。","targetForm":"pair","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pants":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"裤子"}],"examples":[{"sentence":"I went to the clothing store yesterday and bought a blue blouse and three pairs of pants.","translation":"昨天我去衣服店买了一件蓝色的衬衫和三件裤子。","targetForm":"pants","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The tailor is going to redo the hem of my pants.","translation":"裁缝师要帮我重新修裤脚。","targetForm":"pants","senseId":"source-n-1","sourceSenseId":"n-1"}]},"parade":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"阅兵"}],"examples":[{"sentence":"I caught sight of a parade on my way home.","translation":"在回家的路上，我看到一场阅兵式。","targetForm":"parade","senseId":"source-n-3","sourceSenseId":"n-3"}]},"panda":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大熊猫"}],"examples":[{"sentence":"When the World Wildlife Fund was founded in 1961, it took the panda as its symbol.","translation":"国际野生动物基金在一九六一年创办的时候，以熊猫为象征。","targetForm":"panda","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The Chinese government has spent a lot of money on research into successful panda breeding in order to increase their birth rate.","translation":"为了提高出生率，中国政府花了很多钱在大熊猫成功繁殖的研究上。","targetForm":"panda","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because of their rarity, pandas have become a world treasure.","translation":"熊猫因为它们的稀有而成为了世界的宝藏。","targetForm":"pandas","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It is estimated that only a few hundred pandas remain, with a small number of them being raised in zoos in China and abroad.","translation":"据估计只有几百只遗留的熊猫，其中的少数圈养在中国和国外的动物园。","targetForm":"pandas","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The Fuzhou Zoo in China's Fujian Province has done more than its counterparts in training pandas.","translation":"中国福建省福州市动物园在训练大熊猫方面做得比它的同行多。","targetForm":"pandas","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pact":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"协定"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"条约"}],"examples":[{"sentence":"The Pact also improves the business environment and creates mechanisms, such as the extension of a research tax rebate, designed to boost innovation.","translation":"公民公约还将改善商业环境、建立扩展旨在提振创新的研究税收优惠等机制。","targetForm":"pact","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"They still attacked us, despite clearly agreeing to sign the non-aggression pact.","translation":"明明签订了互不侵犯条约，竟然还来攻击我们。","targetForm":"pact","senseId":"source-n-3","sourceSenseId":"n-3"}]},"panel":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"专题讨论小组"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"嵌板"}],"examples":[{"sentence":"Instead, the panel recommended focusing investment on research into climate engineering as a short-term response, and on non-carbon-based energy as a longer-term response.","translation":"相反，专家组建议将投资重点放在气候工程研究��以作为短期的应对措施，并将无碳基能源的研究来作为长期应对措施。","targetForm":"panel","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The craft has two massive solar panels, 7 meters each, that will provide the power it needs to travel 850 million kilometers from the sun.","translation":"该飞行器有两个直径 7 公尺巨大太阳能电池板，为其提供从太阳出发飞行 8.5 亿公里所需的动力。","targetForm":"panels","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Since I installed solar panels on my house, my energy bill has been cut in half.","translation":"自从我在我的房子上装了太阳能电池板，我的电费单就减半了。","targetForm":"panels","senseId":"source-n-1","sourceSenseId":"n-1"}]},"paralyze":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使瘫痪"}],"examples":[{"sentence":"In short, China is veritably humming with energy, money, plans, leadership, and forward motion, while the West seems paralyzed.","translation":"简而言之，当西方陷入瘫痪之时，中国却在能源、资金、计划和领导层的共同作用下活跃起来，并进一��向前发展。","targetForm":"paralyzed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"parcel":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"包裹"}],"examples":[{"sentence":"I paid 2,000 yen for the parcel to be sent by air.","translation":"我花了两千日圆把包裹空运寄出去。","targetForm":"parcel","senseId":"source-n-1","sourceSenseId":"n-1"}]},"passive":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"被动的"}],"examples":[{"sentence":"It is clearly shown in Johnson's investigation that passive smoking is very harmful.","translation":"在Johnson的调查里，明确地证明了二手烟是很有害的。","targetForm":"passive","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"pale":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"界线"}],"examples":[{"sentence":"He told me that I looked pale and asked me what the matter was.","translation":"他跟我说我很苍白，并问我怎么了。","targetForm":"pale","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A gleam of real pride quickened most ingenuously in the Older Man's pale blue eyes.","translation":"老人淡蓝色的眼睛闪过一丝真诚的骄傲。","targetForm":"pale","senseId":"source-n-2","sourceSenseId":"n-2"}]},"passage":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"通道"}],"examples":[{"sentence":"To endanger this passage is to endanger the world economy’s energy lifeline.","translation":"因此，在人们考虑也门的未来的时候，怎么强调这其中的利害关系都不过分。","targetForm":"passage","senseId":"source-n-1","sourceSenseId":"n-1"}]},"parent":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"父母"}],"examples":[{"sentence":"John, who is the youngest in a family of seven, is the apple of his parents' eyes.","translation":"约翰是七口之家中最年幼的，是父母的心头肉。","targetForm":"parents","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Your problem is that you think you have to do everything your parents tell you to do.","translation":"你的问题在于，你认为你必须听从父母的一切指示。","targetForm":"parents","senseId":"source-n-1","sourceSenseId":"n-1"}]},"painter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"画家"}],"examples":[{"sentence":"He is a painter, but he can't paint in the traditional Chinese style.","translation":"他是个画家，但他不会画国画。","targetForm":"painter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He's a painter, but he doesn't do traditional Chinese painting.","translation":"他是个画家，但他不会画国画。","targetForm":"painter","senseId":"source-n-1","sourceSenseId":"n-1"}]},"park":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"公园"}],"examples":[{"sentence":"No matter how cold the weather is, I go to the park every day to run.","translation":"不管天气多么冷，我每天都去公园跑步。","targetForm":"park","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom and I sat on a bench in the park and talked while we fed pigeons.","translation":"我和汤姆在公园的长椅上坐着，一边聊天一边喂着鸽子。","targetForm":"park","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I went to the Hsinchu Science Park during summer vacation and saw many high-tech companies.","translation":"我暑假去了新竹科技园区，见识了许多高科技公司。","targetForm":"park","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When my brother was young, I often used to take him to the park.","translation":"我弟弟小的时候，我常常陪他去公园。","targetForm":"park","senseId":"source-n-1","sourceSenseId":"n-1"}]},"paste":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"糊状物"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"粘贴"}],"examples":[{"sentence":"I could eat some beef noodle soup, or some reheated rice with soybean paste like that, no problem.","translation":"我可以不慌不忙吃牛奶面包鸡蛋，或者泡饭酱菜。","targetForm":"paste","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Country girls like to cut red paper into peach and plum blossoms and paste them onto doors and windows.","translation":"农村的女孩喜欢把红色的纸裁减成桃和李的花及贴在门窗上。","targetForm":"paste","senseId":"source-n-5","sourceSenseId":"n-5"}]},"parameter":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"参数"}],"examples":[{"sentence":"The general parameters of a long-term, two-state agreement are well known.","translation":"一个长期的、巴以两国共存的协议总体范围是众所周知的。","targetForm":"parameters","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"This function takes two parameters, the first one is the title of the window, the second one will be the title of the icon.","translation":"这个函数有两个参数，第一个是窗体的标题，另一个是图标的标题。","targetForm":"parameters","senseId":"source-n-3","sourceSenseId":"n-3"}]},"parallel":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"平行"}],"examples":[{"sentence":"A parallelogram is a quadrilateral formed from two sets of parallel lines.","translation":"平行四边形是由两组平行线组成的四边形。","targetForm":"parallel","senseId":"source-n-1","sourceSenseId":"n-1"}]},"page":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"页"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"记录"}],"examples":[{"sentence":"By turning the page, we can dismiss the characters in a book without fear of hurting their feelings.","translation":"书页翻动之间，我们可以对书中的人物不予理会而不伤及他们的情感。","targetForm":"page","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The world is a book, and those who do not travel read only a page.","translation":"世界是本书，不旅游的人只看了一页。","targetForm":"page","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I think that Tom and I are on the same page.","translation":"我认为我和汤姆的想法一致。","targetForm":"page","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The world is just like a book, and every step you take is like turning a page.","translation":"世界就像是一本书，走一步等于翻了一页。","targetForm":"page","senseId":"source-n-1","sourceSenseId":"n-1"}]}}};
